import ast

# Parse the code for syntax validation only
user_code = code
try:
    tree = ast.parse(user_code)
except SyntaxError as e:
    raise AssertionError(f'Syntax error in your code: {e}')

# Check for numpy import
found_numpy = False
for node in ast.walk(tree):
    if isinstance(node, ast.Import) and any(name.name == 'numpy' for name in node.names):
        found_numpy = True
    if isinstance(node, ast.ImportFrom) and node.module == 'numpy':
        found_numpy = True

if not found_numpy:
    raise AssertionError('Task 1: Missing import numpy (check syntax)')

# Check for vectorized addition (array + number)
found_addition = False
for node in ast.walk(tree):
    if isinstance(node, ast.BinOp) and isinstance(node.op, ast.Add):
        found_addition = True
        break

if not found_addition:
    raise AssertionError('Task 2: Missing vectorized addition (stock_prices + 5)')

# Check for .mean() method call
found_mean = False
for node in ast.walk(tree):
    if isinstance(node, ast.Call):
        if isinstance(node.func, ast.Attribute) and node.func.attr == 'mean':
            found_mean = True
            break

if not found_mean:
    raise AssertionError('Task 4: Missing .mean() method call')

# Check for print statements (at least 2)
print_calls = [node for node in ast.walk(tree) if isinstance(node, ast.Call) and 
               isinstance(node.func, ast.Name) and node.func.id == 'print']

if len(print_calls) < 2:
    raise AssertionError('Tasks 3 & 5: Expected at least 2 print statements')

print('TEST_PASSED')
